importScripts('./zxing-reader.js');
const options={formats:['EAN13','EAN8','UPCA','UPCE','Code128','ITF','DataBar','DataMatrix','QRCode'],tryHarder:true,tryRotate:true,tryInvert:true,tryDownscale:true,tryDenoise:false,maxNumberOfSymbols:2,textMode:'Plain'};
async function decodeFrame(image,enhance){const fast={...options,tryHarder:false,tryInvert:false,tryDownscale:false,maxNumberOfSymbols:1};let rows=await ZXingWASM.readBarcodes(image,fast);if(!rows.length&&enhance)rows=await ZXingWASM.readBarcodes(image,options);if(!rows.length&&enhance)rows=await ZXingWASM.readBarcodes(image,{...options,binarizer:'GlobalHistogram'});if(!rows.length&&enhance){const inverted={...image,data:image.data.map((v,i)=>i%4===3?v:255-v)};rows=await ZXingWASM.readBarcodes(inverted,options)}return rows}
let ready;
self.onmessage=async({data})=>{try{if(data.type==='init'){ready=(async()=>{const response=await fetch('./zxing_reader.wasm');if(!response.ok)throw Error('decoder-load');const binary=new Uint8Array(await response.arrayBuffer());await ZXingWASM.prepareZXingModule({fireImmediately:true,overrides:{wasmBinary:binary}});self.postMessage({type:'ready'})})();await ready;return}await ready;const image={width:data.width,height:data.height,data:new Uint8ClampedArray(data.buffer)};const rows=await decodeFrame(image,data.enhance);self.postMessage({type:'result',rows:rows.map(r=>({text:r.text,format:r.format}))})}catch(error){self.postMessage({type:'error',message:error.message})}};
